const profiles={
 approval:{name:'审批与商业化',labels:['药品审批'],checks:[['获批范围','适应症、地区与正式生效时间'],['增量市场','患者范围、竞品与支付能力'],['收入兑现','准入、定价、销售与原有预期']]},
 clinical:{name:'临床与管线风险',labels:['临床失败'],checks:[['终点与阶段','失败范围、后续试验与终止状态'],['项目权重','收入预期、研发占比与替代管线'],['损失边界','减值、现金消耗与集团承受力']]},
 order:{name:'订单与交付',labels:['重大订单'],checks:[['真正增量','新订单还是旧承诺转正式合同'],['兑现路径','交付排期、产能与取消条款'],['现金流','预付款、利润率与市场预期']]},
 deal:{name:'并购与重组',labels:['重大收购','重大重组'],checks:[['交易阶段','意向、协议、审批还是已交割'],['经济代价','估值、融资、稀释与控制权'],['兑现与失败','协同证据、整合成本与终止条件']]},
 policy:{name:'政策与监管',labels:['监管调查','政策约束'],checks:[['法律状态','调查、草案还是生效措施'],['公司敞口','受影响业务、项目与地区'],['影响边界','处罚、整改成本与可能恢复时间']]},
 supply:{name:'供给冲击',labels:['供给冲击','能源供给拐点'],checks:[['冲击强度','产能占比、库存与停产范围'],['持续时间','复产条件、替代供应与需求'],['影响分化','矿主损失与同行价格受益分开']]},
 denial:{name:'反证与撤销',labels:['传闻与反证'],checks:[['消息沿革','原始传闻、正式回应与修订'],['可信程度','来源独立性、权威性与冲突'],['交易复核','撤销旧前提，检查已有敞口']]},
 recall:{name:'召回与经营风险',labels:['产品召回'],checks:[['受影响范围','车型、年份、地区与严重性'],['实际成本','数量不直接等于赔付金额'],['后续变化','补救、销量与监管升级']]},
 capital:{name:'资本回报',labels:['资本回报'],checks:[['授权与执行','董事会额度不等于已回购'],['财务能力','现金流、融资和净负债约束'],['每股影响','执行价格、注销与稀释抵消']]},
 product:{name:'产品与生态',labels:['产品与战略','产品突破','生态分化'],checks:[['采用真实性','排名、开放政策与使用数据'],['持续性','留存、频率、成本与替代品'],['受益归属','收费权、利润与上市公司映射']]},
 cluster:{name:'多因素与全球传导',labels:['复合假设','全球联动'],checks:[['独立证据','去重后是否出现多源同向变化'],['机制与敞口','产品差异、替代关系与盈利弹性'],['跨市场预期','汇率、收盘时点和本地计价差']]}
};
export function eventProfile(topic){return Object.entries(profiles).map(([id,p])=>({...p,id})).find(p=>p.id===topic?.categoryId||p.labels.includes(topic?.label))||{id:'general',name:'事件核验',checks:[['事件增量','与历史背景相比改变了什么'],['公司影响','业务与盈利传导是否成立'],['触发条件','价格、期限与失效条件是否明确']]};}
export const eventGroups=Object.entries(profiles).map(([id,p])=>({id,name:p.name}));
